package com.ultraop.mocap;

import com.ultraop.mocap.command.MoCapCommand;import com.ultraop.mocap.command.ParityMoCapCommand;import com.ultraop.mocap.command.RootMoCapCommand;import com.ultraop.mocap.playback.PlaybackManager;import com.ultraop.mocap.recording.RecordingActionListener;import com.ultraop.mocap.recording.RecordingBlockListener;import com.ultraop.mocap.recording.RecordingBreakProgressListener;import com.ultraop.mocap.recording.RecordingChatListener;import com.ultraop.mocap.recording.RecordingContainerListener;import com.ultraop.mocap.recording.RecordingManager;import com.ultraop.mocap.recording.RecordingRespawnListener;import com.ultraop.mocap.scene.SceneManager;import org.bukkit.event.EventHandler;import org.bukkit.event.Listener;import org.bukkit.event.player.PlayerJoinEvent;import org.bukkit.plugin.java.JavaPlugin;import java.io.IOException;

public final class MoCapPaperPlugin extends JavaPlugin {
    private RecordingManager recordingManager;private PlaybackManager playbackManager;private SceneManager sceneManager;private MoCapCommand mocapCommand;private RootMoCapCommand rootCommand;private ParityMoCapCommand parityCommand;
    @Override public void onEnable(){saveDefaultConfig();recordingManager=new RecordingManager(this);recordingManager.start();getServer().getPluginManager().registerEvents(new RecordingBlockListener(recordingManager),this);getServer().getPluginManager().registerEvents(new RecordingBreakProgressListener(recordingManager),this);getServer().getPluginManager().registerEvents(new RecordingActionListener(recordingManager),this);getServer().getPluginManager().registerEvents(new RecordingChatListener(recordingManager),this);getServer().getPluginManager().registerEvents(new RecordingContainerListener(recordingManager),this);getServer().getPluginManager().registerEvents(new RecordingRespawnListener(recordingManager),this);getServer().getPluginManager().registerEvents(new Listener(){@EventHandler public void onJoin(PlayerJoinEvent e){if(!getConfig().getBoolean("settings.experimental_release_warning",true)||!e.getPlayer().isOp())return;e.getPlayer().sendMessage("§6MoCap Paper is an experimental alpha release. §eUse with caution; report issues on GitHub: §nhttps://github.com/Ahsan3944/mocap-paper§r");e.getPlayer().sendMessage("§7Disable this warning with: §f/mocap settings experimental_release_warning false");}},this);sceneManager=new SceneManager(this,recordingManager);try{sceneManager.start();}catch(IOException e){getLogger().severe("Unable to initialize scene directory: "+e.getMessage());getServer().getPluginManager().disablePlugin(this);return;}playbackManager=new PlaybackManager(this,recordingManager);recordingManager.setPlaybackManager(playbackManager);playbackManager.setSceneManager(sceneManager);playbackManager.start();mocapCommand=new MoCapCommand(this,recordingManager,playbackManager);rootCommand=new RootMoCapCommand(mocapCommand,sceneManager,this,recordingManager,playbackManager);parityCommand=new ParityMoCapCommand(rootCommand,playbackManager);if(getCommand("mocap")==null){getLogger().severe("The /mocap command is not registered in plugin.yml.");getServer().getPluginManager().disablePlugin(this);return;}getCommand("mocap").setExecutor(parityCommand);getCommand("mocap").setTabCompleter(parityCommand);getLogger().info("MoCap Paper initialized for Minecraft 1.21.11.");}
    public PlaybackManager getPlaybackManager(){return playbackManager;}public SceneManager getSceneManager(){return sceneManager;}@Override public void onDisable(){if(mocapCommand!=null)mocapCommand.shutdown();if(playbackManager!=null)playbackManager.shutdown();if(recordingManager!=null)recordingManager.shutdown();}
}